const RESERVED = new Set();
const key = (x, y, z) => `${x},${y},${z}`;
export function reserve(x0, y0, z0, x1 = x0, y1 = y0, z1 = z0) {
  for (let x = Math.min(x0, x1); x <= Math.max(x0, x1); x++)
    for (let y = Math.min(y0, y1); y <= Math.max(y0, y1); y++)
